class BankAccount {
    protected String accountNumber;
    protected double balance;

    public BankAccount(String accNum, double initialBalance) {
        this.accountNumber = accNum;
        this.balance = initialBalance;
    }

    public void deposit(double amount) {
        this.balance += amount;
        System.out.println(accountNumber + " credited: $" + amount + ", Balance: $" + balance);
    }
}

// Single direct parent: BankAccount
class SavingsAccount extends BankAccount {
    private double interestRatePercentage;

    public SavingsAccount(String accNum, double balance, double interestRate) {
        super(accNum, balance);
        this.interestRatePercentage = interestRate;
    }

    public void creditInterest() {
        double interest = balance * (interestRatePercentage / 100.0);
        deposit(interest); // Calls single inherited parent method
        System.out.println("Interest of $" + interest + " successfully credited");
    }
}

public class SingleInheritanceDemo {
    public static void main(String[] args) {
        SavingsAccount sa = new SavingsAccount("SAV-303", 2000.0, 4.5);
        sa.deposit(500.0);
        sa.creditInterest();
    }
}

