class Account {
    protected String accountNumber;
    protected double balance;

    public Account(String accountNumber, double balance) {
        this.accountNumber = accountNumber;
        this.balance = balance;
    }
}

class LoanAccount extends Account {
    private double originalPrincipal;

    public LoanAccount(String accountNumber, double principal) {
        super(accountNumber, principal);
        this.originalPrincipal = principal;
    }

    public void makePayment(double amount) {
        balance -= amount;
        if (balance <= 0) {
            System.out.println("Loan " + accountNumber + " payment: $" + amount + ". Loan fully paid off!");
        } else {
            System.out.println("Loan " + accountNumber + " payment: $" + amount + ". Remaining balance: $" + balance);
        }
    }
}

public class Main {
    public static void main(String[] args) {
        LoanAccount loan = new LoanAccount("LN-101", 5000.0);
        loan.makePayment(500.0);
        loan.makePayment(4500.0);
    }
}

