practiceProblems.solutionCode:
class Phone {
    public void call() { System.out.println("Calling..."); }
}

class Camera {
    private int megapixels;
    public Camera(int megapixels) { this.megapixels = megapixels; }
    public void snap() { System.out.println("Photo captured with " + megapixels + "MP sensor"); }
}

// Single inheritance from Phone + composition with Camera
class Smartphone extends Phone {
    private Camera camera;

    public Smartphone(int megapixels) {
        this.camera = new Camera(megapixels);
    }

    public void takePhoto() {
        camera.snap();
    }
}

public class Main {
    public static void main(String[] args) {
        Smartphone sp = new Smartphone(48);
        sp.call();
        sp.takePhoto();
    }
}

class Employee {
    protected String empId;
    protected String name;
    protected double baseSalary;

    public Employee(String empId, String name, double baseSalary) {
        this.empId = empId;
        this.name = name;
        this.baseSalary = baseSalary;
    }
}

class Manager extends Employee {
    private double teamBonusRate;
    private int directReports;

    public Manager(String empId, String name, double baseSalary, double bonusRate, int reports) {
        super(empId, name, baseSalary);
        this.teamBonusRate = bonusRate;
        this.directReports = reports;
    }

    public double computeAnnualPackage() {
        double bonus = baseSalary * (teamBonusRate / 100.0);
        double reportBonus = directReports * 1000.0;
        return baseSalary + bonus + reportBonus;
    }

    public void printPackage() {
        System.out.println("Manager " + empId + " (" + name + ") Total Package: $" + computeAnnualPackage() + " (Direct Reports: " + directReports + ")");
    }
}

public class Main {
    public static void main(String[] args) {
        Manager m = new Manager("M-44", "David", 120000.0, 12.5, 7);
        m.printPackage();
    }
}
